use vstd::prelude::*;

verus! {

    /// Returns a new vector containing the same elements in the same order
    /// as the input vector `a`.  The input is not modified.
    fn copy<T: Copy>(a: &Vec<T>) -> (result: Vec<T>)
        ensures
            // The output has the same length as the input.
            result.len() == a.len(),
        ensures
            // For every valid index, the elements coincide.
            forall |i: usize| i < a.len() ==> result[i] == a[i]
    {
        let mut result: Vec<T> = Vec::new();
        let mut i: usize = 0;
        while i < a.len()
            invariant
                // index stays in bounds
                i <= a.len(),
                // we've copied exactly i elements so far
                result.len() == i,
                // and they agree with the prefix of a
                forall |j: usize| j < i ==> result[j] == a[j],
            decreases a.len() - i,
        {
            // Vec::push in Vstd is specified to:
            //  * increment len by 1
            //  * preserve all old entries
            //  * set the new entry at index old_len
            result.push(a[i]);
            i += 1;
        }
        result
    }

}